def transform(grid):
    h, w = len(grid), len(grid[0])
    # Background is a cyclic diagonal field. Infer period and phase colors
    # from the nonzero samples at r-c diagonals, then extrapolate the cycle.
    samples = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                samples[(r-c)] = v
    period = 7
    palette = {}
    for d, v in samples.items():
        k = d % period
        if k not in palette:
            palette[k] = v
    # Repeating sampled diagonal colors uniquely determine the seven-color cycle.
    for k in range(period):
        if k not in palette:
            # interpolate from the nearest observed phase in the cycle
            known = min(palette, key=lambda q: (k-q) % period)
            palette[k] = palette[known]
    return [[palette[(r-c) % period] for c in range(w)] for r in range(h)]
